CREATE TABLE providers (provider_id TEXT PRIMARY KEY, name TEXT NOT NULL, website_url TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE models (model_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES providers(provider_id) ON DELETE RESTRICT, name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','preview','retired')), released_on TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE INDEX idx_models_provider_status ON models(provider_id, status);
CREATE TABLE model_versions (model_version_id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES models(model_id) ON DELETE RESTRICT, version TEXT NOT NULL, provider_model_key TEXT NOT NULL, is_current INTEGER NOT NULL DEFAULT 0 CHECK(is_current IN (0,1)), created_at TEXT NOT NULL, UNIQUE(model_id, version)) STRICT;
CREATE UNIQUE INDEX uq_model_versions_current ON model_versions(model_id) WHERE is_current=1;
CREATE TABLE benchmark_suites (suite_id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE benchmark_suite_versions (suite_version_id TEXT PRIMARY KEY, suite_id TEXT NOT NULL REFERENCES benchmark_suites(suite_id) ON DELETE RESTRICT, phase_id TEXT NOT NULL CHECK(phase_id IN ('debate','plan','build')), version TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, definition_sha256 TEXT NOT NULL CHECK(length(definition_sha256)=64), is_current INTEGER NOT NULL DEFAULT 0 CHECK(is_current IN (0,1)), created_at TEXT NOT NULL, UNIQUE(suite_id,version), UNIQUE(definition_sha256)) STRICT;
CREATE UNIQUE INDEX uq_suite_versions_current ON benchmark_suite_versions(suite_id) WHERE is_current=1;
CREATE INDEX idx_suite_versions_phase ON benchmark_suite_versions(phase_id,suite_id,version);
CREATE TABLE benchmark_case_versions (case_version_id TEXT PRIMARY KEY, case_id TEXT NOT NULL, suite_version_id TEXT NOT NULL REFERENCES benchmark_suite_versions(suite_version_id) ON DELETE RESTRICT, name TEXT NOT NULL, description TEXT NOT NULL, benchmark_set TEXT NOT NULL CHECK(benchmark_set IN ('fixed','hidden')), evaluation_method TEXT NOT NULL CHECK(evaluation_method IN ('automated-tests','ai-judge','hybrid')), position INTEGER NOT NULL CHECK(position>=0), max_attempts INTEGER NOT NULL CHECK(max_attempts>0), expected_input_tokens INTEGER NOT NULL CHECK(expected_input_tokens>=0), expected_output_tokens INTEGER NOT NULL CHECK(expected_output_tokens>=0), definition_sha256 TEXT NOT NULL CHECK(length(definition_sha256)=64), protected_definition_ref TEXT, UNIQUE(suite_version_id,case_id), UNIQUE(suite_version_id,position), UNIQUE(case_version_id,suite_version_id)) STRICT;
CREATE INDEX idx_case_versions_suite_position ON benchmark_case_versions(suite_version_id,position);
CREATE TABLE execution_versions (execution_version_id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('runner','prompt','evaluator')), version TEXT NOT NULL, definition_sha256 TEXT NOT NULL CHECK(length(definition_sha256)=64), safe_metadata_json TEXT, created_at TEXT NOT NULL, UNIQUE(kind,version), UNIQUE(kind,definition_sha256)) STRICT;
CREATE TABLE benchmark_runs (run_id TEXT PRIMARY KEY, suite_version_id TEXT NOT NULL REFERENCES benchmark_suite_versions(suite_version_id) ON DELETE RESTRICT, model_version_id TEXT NOT NULL REFERENCES model_versions(model_version_id) ON DELETE RESTRICT, runner_version_id TEXT NOT NULL REFERENCES execution_versions(execution_version_id) ON DELETE RESTRICT, prompt_version_id TEXT NOT NULL REFERENCES execution_versions(execution_version_id) ON DELETE RESTRICT, status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled')), queued_at TEXT NOT NULL, started_at TEXT, completed_at TEXT, model_configuration_json TEXT NOT NULL, configuration_sha256 TEXT NOT NULL CHECK(length(configuration_sha256)=64), failure_classification TEXT, diagnostic_summary TEXT, UNIQUE(run_id,suite_version_id), CHECK(started_at IS NULL OR started_at>=queued_at), CHECK(completed_at IS NULL OR (started_at IS NOT NULL AND completed_at>=started_at)), CHECK(status NOT IN ('completed','failed','cancelled') OR completed_at IS NOT NULL)) STRICT;
CREATE INDEX idx_runs_started ON benchmark_runs(started_at DESC);
CREATE INDEX idx_runs_model_status ON benchmark_runs(model_version_id,status);
CREATE TABLE benchmark_case_results (result_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, suite_version_id TEXT NOT NULL, case_version_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('passed','failed','error')), attempt_count INTEGER NOT NULL CHECK(attempt_count>0), evaluator_version_id TEXT REFERENCES execution_versions(execution_version_id) ON DELETE RESTRICT, diagnostic_summary TEXT, created_at TEXT NOT NULL, UNIQUE(run_id,case_version_id), FOREIGN KEY(run_id,suite_version_id) REFERENCES benchmark_runs(run_id,suite_version_id), FOREIGN KEY(case_version_id,suite_version_id) REFERENCES benchmark_case_versions(case_version_id,suite_version_id)) STRICT;
CREATE TABLE benchmark_result_metrics (result_id TEXT PRIMARY KEY REFERENCES benchmark_case_results(result_id) ON DELETE RESTRICT, quality_score REAL NOT NULL CHECK(quality_score BETWEEN 0 AND 100), automated_tests_passed INTEGER NOT NULL CHECK(automated_tests_passed>=0), automated_tests_total INTEGER NOT NULL CHECK(automated_tests_total>=automated_tests_passed), judge_score REAL CHECK(judge_score BETWEEN 0 AND 100), cost_usd REAL NOT NULL CHECK(cost_usd>=0), latency_ms INTEGER NOT NULL CHECK(latency_ms>=0), input_tokens INTEGER NOT NULL CHECK(input_tokens>=0), output_tokens INTEGER NOT NULL CHECK(output_tokens>=0)) STRICT;
CREATE TABLE daily_model_summaries (summary_date TEXT NOT NULL, phase_id TEXT NOT NULL CHECK(phase_id IN ('debate','plan','build')), model_version_id TEXT NOT NULL REFERENCES model_versions(model_version_id) ON DELETE RESTRICT, derivation_version TEXT NOT NULL, completed_run_count INTEGER NOT NULL CHECK(completed_run_count>=0), metrics_json TEXT NOT NULL, source_cutoff_at TEXT NOT NULL, input_evidence_sha256 TEXT NOT NULL CHECK(length(input_evidence_sha256)=64), created_at TEXT NOT NULL, PRIMARY KEY(summary_date,phase_id,model_version_id,derivation_version)) STRICT;
CREATE TABLE recommendations (recommendation_id TEXT PRIMARY KEY, recommendation_date TEXT NOT NULL, phase_id TEXT NOT NULL CHECK(phase_id IN ('debate','plan','build')), priority_id TEXT NOT NULL CHECK(priority_id IN ('quality','value','speed','reliability','balanced')), derivation_version TEXT NOT NULL, source_summary_sha256 TEXT NOT NULL CHECK(length(source_summary_sha256)=64), created_at TEXT NOT NULL, UNIQUE(recommendation_date,phase_id,priority_id,derivation_version)) STRICT;
CREATE TABLE recommendation_entries (recommendation_id TEXT NOT NULL REFERENCES recommendations(recommendation_id) ON DELETE RESTRICT, model_version_id TEXT NOT NULL REFERENCES model_versions(model_version_id) ON DELETE RESTRICT, rank INTEGER NOT NULL CHECK(rank>0), score REAL NOT NULL CHECK(score BETWEEN 0 AND 100), dimensions_json TEXT NOT NULL, explanations_json TEXT NOT NULL, PRIMARY KEY(recommendation_id,model_version_id), UNIQUE(recommendation_id,rank)) STRICT;
CREATE TABLE benchmark_attempts (attempt_id TEXT PRIMARY KEY, result_id TEXT NOT NULL REFERENCES benchmark_case_results(result_id) ON DELETE RESTRICT, attempt_number INTEGER NOT NULL CHECK(attempt_number>0), status TEXT NOT NULL CHECK(status IN ('passed','failed','error')), started_at TEXT NOT NULL, completed_at TEXT, provider_request_id TEXT, cost_usd REAL NOT NULL CHECK(cost_usd>=0), latency_ms INTEGER NOT NULL CHECK(latency_ms>=0), input_tokens INTEGER NOT NULL CHECK(input_tokens>=0), output_tokens INTEGER NOT NULL CHECK(output_tokens>=0), error_classification TEXT, UNIQUE(result_id,attempt_number), CHECK(completed_at IS NULL OR completed_at>=started_at)) STRICT;
CREATE INDEX idx_attempts_result ON benchmark_attempts(result_id,attempt_number);
